CREATE TABLE IF NOT EXISTS records (id SERIAL PRIMARY KEY, name TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS users (id SERIAL PRIMARY KEY, contact TEXT NOT NULL UNIQUE, display_name TEXT NOT NULL DEFAULT 'Student', created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), last_login_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS auth_tokens (id SERIAL PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,token_hash TEXT NOT NULL UNIQUE,expires_at TIMESTAMPTZ NOT NULL,used_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS sessions (id SERIAL PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,session_hash TEXT NOT NULL UNIQUE,expires_at TIMESTAMPTZ NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS roles (id SERIAL PRIMARY KEY,name TEXT UNIQUE NOT NULL);
INSERT INTO roles(name) VALUES ('student'),('instructor'),('admin') ON CONFLICT DO NOTHING;
CREATE TABLE IF NOT EXISTS user_roles (user_id INTEGER REFERENCES users(id) ON DELETE CASCADE,role_id INTEGER REFERENCES roles(id) ON DELETE CASCADE,PRIMARY KEY(user_id,role_id));
CREATE TABLE IF NOT EXISTS student_profiles (id SERIAL PRIMARY KEY,user_id INTEGER UNIQUE NOT NULL REFERENCES users(id) ON DELETE CASCADE,phone TEXT,address TEXT,emergency_contact TEXT,created_at TIMESTAMPTZ DEFAULT NOW(),updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS instructor_profiles (id SERIAL PRIMARY KEY,user_id INTEGER UNIQUE NOT NULL REFERENCES users(id) ON DELETE CASCADE,bio TEXT,license_number TEXT,active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS lesson_types (id SERIAL PRIMARY KEY,name TEXT NOT NULL UNIQUE,description TEXT,duration_minutes INTEGER NOT NULL DEFAULT 60,price_cents INTEGER NOT NULL DEFAULT 0,active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS instructor_availability (id SERIAL PRIMARY KEY,instructor_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,weekday SMALLINT NOT NULL CHECK(weekday BETWEEN 0 AND 6),start_time TIME NOT NULL,end_time TIME NOT NULL,available BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS bookings (id SERIAL PRIMARY KEY,student_id INTEGER NOT NULL REFERENCES users(id),instructor_id INTEGER NOT NULL REFERENCES users(id),lesson_type_id INTEGER NOT NULL REFERENCES lesson_types(id),starts_at TIMESTAMPTZ NOT NULL,ends_at TIMESTAMPTZ NOT NULL,status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','confirmed','cancelled','completed')),notes TEXT,created_at TIMESTAMPTZ DEFAULT NOW(),updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS payments (id SERIAL PRIMARY KEY,booking_id INTEGER REFERENCES bookings(id) ON DELETE SET NULL,user_id INTEGER NOT NULL REFERENCES users(id),amount_cents INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'pending',provider_reference TEXT,created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS notifications (id SERIAL PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,title TEXT NOT NULL,message TEXT NOT NULL,read_at TIMESTAMPTZ,created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS audit_log (id BIGSERIAL PRIMARY KEY,user_id INTEGER REFERENCES users(id) ON DELETE SET NULL,action TEXT NOT NULL,entity_type TEXT,entity_id TEXT,metadata JSONB NOT NULL DEFAULT '{}',created_at TIMESTAMPTZ DEFAULT NOW());
CREATE INDEX IF NOT EXISTS bookings_schedule_idx ON bookings(instructor_id,starts_at);
